import{_ as e,o as t,c as a,ae as n}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-08-11","description":"","frontmatter":{"date":"2026-08-11T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-08-11-uxtrend.md","filePath":"daily/2026-08-11-uxtrend.md"}'),o={name:"daily/2026-08-11-uxtrend.md"};function s(i,r,g,p,d,h){return t(),a("div",null,[...r[0]||(r[0]=[n('<h1 id="设计趋势-2026-08-11" tabindex="-1">设计趋势 - 2026-08-11 <a class="header-anchor" href="#设计趋势-2026-08-11" aria-label="Permalink to &quot;设计趋势 - 2026-08-11&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势聚焦于AI与用户体验的融合。代理UX设计原则、AI工作流优化、以及AI代理的Agent Experience成为讨论热点。Figma的AI工作流程为创意项目提供新起点。2026年设计师调查显示，AI显著提升设计品质。最值得关注的是AI在提升设计质量和用户体验设计的新维度。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 探讨了设计新型数字设备用户体验的代理UX设计原则。</p><p><strong>能解决什么问题</strong>: 如何确保在AI驱动的代理系统中以人为中心。</p><p><strong>产品应用</strong>: 适用于任何产品开发过程，通过以用户问题为中心来设计解决方案。</p><p><strong>示例场景</strong>: 使用AI代理系统辅助团队协作和问题解决。</p><hr><h3 id="_2-ai工作流设计的误区-模仿人类而非优化功能" tabindex="-1">2. AI工作流设计的误区：模仿人类而非优化功能 <a class="header-anchor" href="#_2-ai工作流设计的误区-模仿人类而非优化功能" aria-label="Permalink to &quot;2. AI工作流设计的误区：模仿人类而非优化功能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://skooloflife.medium.com/the-biggest-mistake-in-ai-workflow-design-mimicking-human-process-instead-of-optimizing-function-628bfa37aa02" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI工作流设计应基于功能优化而非模仿人类行为。</p><p><strong>能解决什么问题</strong>: 解决AI工作流设计中将AI视为“某人”而非“某物”的错误观念。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过直接嵌入功能而非模拟人类工作流程。</p><p><strong>示例场景</strong>: 在客服系统中，直接调用AI接口处理查询而非模拟人工对话。</p><hr><h3 id="_3-人工智能时代下的用户体验2-0-agent-experience" tabindex="-1">3. 人工智能时代下的用户体验2.0（Agent Experience） <a class="header-anchor" href="#_3-人工智能时代下的用户体验2-0-agent-experience" aria-label="Permalink to &quot;3. 人工智能时代下的用户体验2.0（Agent Experience）&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@purvashobhit/ux-2-0-agent-experience-experience-design-in-the-age-of-ai-agents-a32230569449" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 用户体验设计扩展至非人类用户，即AI代理。</p><p><strong>能解决什么问题</strong>: 如何为非人类用户设计无缝、直观、满意的体验。</p><p><strong>产品应用</strong>: 可应用于人机协作系统，提升交互效率和信任度。</p><p><strong>示例场景</strong>: AI代理代替人类预约医生，提高预约流程效率。</p><hr><h3 id="_4-figma中的ai工作流程-图像、视频与创意生成" tabindex="-1">4. Figma中的AI工作流程：图像、视频与创意生成 <a class="header-anchor" href="#_4-figma中的ai工作流程-图像、视频与创意生成" aria-label="Permalink to &quot;4. Figma中的AI工作流程：图像、视频与创意生成&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/community/ai-workflows" target="_blank" rel="noreferrer">AI Workflows for Image, Video &amp; Creative Generation | Figma</a></p><p><strong>一句话摘要</strong>: AI工作流程提供结构化的起点，帮助用户自定义创意项目。</p><p><strong>能解决什么问题</strong>: 解决AI创意生成过程中模型选择和创意步骤的复杂性。</p><p><strong>产品应用</strong>: 适用于实际产品，通过自定义输入和探索变化适应创意过程。</p><p><strong>示例场景</strong>: 为营销活动生成产品图像和视觉故事。</p><hr><h3 id="_5-2026年设计师现状-ai提升设计品质" tabindex="-1">5. 2026年设计师现状：AI提升设计品质 <a class="header-anchor" href="#_5-2026年设计师现状-ai提升设计品质" aria-label="Permalink to &quot;5. 2026年设计师现状：AI提升设计品质&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/product-designers-are-not-being-replaced-they-are-being-sorted-6e2fb0492ed2" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 91%的设计师认为AI提高了设计质量而非仅速度。</p><p><strong>能解决什么问题</strong>: AI辅助设计提升了效率和质量，但人类设计师仍需完成最后的细节。</p><p><strong>产品应用</strong>: 适用于产品设计，AI辅助初步设计，人类设计师完成细节和策略。</p><p><strong>示例场景</strong>: 设计师使用AI生成初步界面，然后进行人工优化。</p><hr><h3 id="_6-ai如何改变我的设计工作流程" tabindex="-1">6. AI如何改变我的设计工作流程 <a class="header-anchor" href="#_6-ai如何改变我的设计工作流程" aria-label="Permalink to &quot;6. AI如何改变我的设计工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@kazdenc/how-my-design-workflow-is-changing-with-ai-bc80e7fa3323" target="_blank" rel="noreferrer">How my design workflow is changing with AI</a></p><p><strong>一句话摘要</strong>: AI让设计工作流程更快速、协作、减少猜测。</p><p><strong>能解决什么问题</strong>: 提高设计效率，减少从想法到原型的时间。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI工具快速迭代原型。</p><p><strong>示例场景</strong>: 使用Figma和Cursor进行交互式原型设计。</p><hr><h3 id="_7-ai与设计-人工智能如何协助设计师以及设计师如何创造ai友好型设计" tabindex="-1">7. AI与设计：人工智能如何协助设计师以及设计师如何创造AI友好型设计 <a class="header-anchor" href="#_7-ai与设计-人工智能如何协助设计师以及设计师如何创造ai友好型设计" aria-label="Permalink to &quot;7. AI与设计：人工智能如何协助设计师以及设计师如何创造AI友好型设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@gwrx2005/ai-and-design-how-artificial-intelligence-assists-designers-and-how-designers-create-ai-friendly-df97320884ae" target="_blank" rel="noreferrer">AI and Design: How Artificial Intelligence Assists Designers and How Designers Create AI‑Friendly…</a></p><p><strong>一句话摘要</strong>: AI驱动产品中对话界面的兴起，设计师需融合对话设计与视觉界面设计。</p><p><strong>能解决什么问题</strong>: 解决用户与AI通过自然语言交互时的用户体验问题。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，如聊天机器人和语音助手，提升用户交互体验。</p><p><strong>示例场景</strong>: 用户通过聊天机器人查询天气预报或预订餐厅。</p><hr><h3 id="_8-2024年产品设计的24个预测" tabindex="-1">8. 2024年产品设计的24个预测 <a class="header-anchor" href="#_8-2024年产品设计的24个预测" aria-label="Permalink to &quot;8. 2024年产品设计的24个预测&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/zalando-design/24-product-design-predictions-for-2024-6b52fb97658c" target="_blank" rel="noreferrer">24 product design predictions for 2024</a></p><p><strong>一句话摘要</strong>: 2024年设计领域将更多采用生成式AI，提升设计效率和个性化体验。</p><p><strong>能解决什么问题</strong>: 解决设计自动化、个性化和伦理问题，提升用户体验。</p><p><strong>产品应用</strong>: 可应用于产品设计，通过AI自动化常规任务，实现个性化设计。</p><p><strong>示例场景</strong>: AI根据用户偏好动态调整产品界面和功能。</p><hr><h3 id="_9-为人工智能设计-设计人工智能特性的交互" tabindex="-1">9. 为人工智能设计：设计人工智能特性的交互 <a class="header-anchor" href="#_9-为人工智能设计-设计人工智能特性的交互" aria-label="Permalink to &quot;9. 为人工智能设计：设计人工智能特性的交互&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@ux.haowu/design-for-ai-2-designing-interactions-for-ai-features-d776d6388bdd" target="_blank" rel="noreferrer">Design for AI 2: Designing Interactions for AI Features</a></p><p><strong>一句话摘要</strong>: AI通过预测意图和实时补全，辅助用户保持专注。</p><p><strong>能解决什么问题</strong>: 提升用户体验，减少输入错误，提高工作效率。</p><p><strong>产品应用</strong>: 适用于需要快速输入和减少错误的场景，如邮件客户端和编程应用。</p><p><strong>示例场景</strong>: Figma中的地址字段自动补全，减少打字和错误。</p><hr><h3 id="_10-ai代理工作流设计模式概览" tabindex="-1">10. AI代理工作流设计模式概览 <a class="header-anchor" href="#_10-ai代理工作流设计模式概览" aria-label="Permalink to &quot;10. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，分类并展示实际案例。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以模拟人类推理，提高任务执行效率。</p><p><strong>产品应用</strong>: 可应用于构建智能代理框架，处理复杂问题。</p><p><strong>示例场景</strong>: 基于这些原则开发智能客服代理。</p><hr>',75)])])}const m=e(o,[["render",s]]);export{c as __pageData,m as default};
